tool_input.new_string:
Reply.prototype.removeTrailer = function (key) {
  if (this[kReplyTrailers] === null) return this
  this[kReplyTrailers][key.toLowerCase()] = undefined
  // when no trailer is left, we reset the state so the response
  // is sent as if no trailer was ever registered
  for (const trailerName in this[kReplyTrailers]) {
    if (typeof this[kReplyTrailers][trailerName] === 'function') return this
  }
  this[kReplyTrailers] = null
  return this
}
